```python
def upload_all(uploader, records):
    failed_ids = []
    batch_size = 10  # As per the documentation, batch size is 10

    for i in range(0, len(records), batch_size):
        batch = records[i:i + batch_size]
        uploader.upload_batch(batch)

        # Check if any records in the batch failed
        for record in batch:
            if not uploader.is_success(record):
                failed_ids.append(record.id)

    # Return the sorted list of failed IDs
    return sorted(failed_ids)
```

