```python
def is_valid_label(label):
    # Rule 1: Length between 6 and 12 characters
    if not (6 <= len(label) <= 12):
        return False

    # Rule 2: First character is a lowercase letter
    if not label[0].islower():
        return False

    # Rule 3: Only lowercase letters, digits, and underscores
    if not all(c in 'abcdefghijklmnopqrstuvwxyz0123456789_' for c in label):
        return False

    # Rule 4: At least one digit
    if label.count('0123456789') == 0:
        return False

    # Rule 5: No two underscores in a row and no trailing underscore
    if '__' in label:
        return False
    if label.endswith('_'):
        return False

    return True
```

